#include <metal_stdlib>
using namespace metal;
constant constexpr uint TILE_M = 64;
constant constexpr uint TILE_N = 64;
constant constexpr uint K_UNROLL = 4;
constant constexpr uint THREADGROUP_SIZE = 32;
constant constexpr uint FP4_PER_WORD = 8;
constant constexpr uint THREAD_ROWS = 8;
constant constexpr uint THREAD_COLS = 16;
constant constexpr uint LOADS_PER_THREAD = (TILE_M * K_UNROLL) / THREADGROUP_SIZE; // 8
// E2M1 lookup table
constant half FP4_LUT[16] = {
half(0.0h), half(0.5h), half(1.0h), half(1.5h),
half(2.0h), half(3.0h), half(4.0h), half(6.0h),
half(-0.0h), half(-0.5h), half(-1.0h), half(-1.5h),
half(-2.0h), half(-3.0h), half(-4.0h), half(-6.0h)
};
inline half dequant_fp4_e2m1(uint nibble, half scale) {
return FP4_LUT[nibble & 0xFu] * scale;
}
kernel void mmfp4_gemm(
device const half* A [[buffer(0)]], // [M, K]
device const uint32_t* B_packed [[buffer(1)]], // [K, N//8]
device const half* B_scales [[buffer(2)]], // [K//group_size, N]
device half* C [[buffer(3)]], // [M, N]
constant uint32_t& M [[buffer(4)]],
constant uint32_t& K [[buffer(5)]],
constant uint32_t& N [[buffer(6)]],
constant uint32_t& group_size [[buffer(7)]],
uint2 gid [[thread_position_in_grid]],
uint2 tid [[thread_position_in_threadgroup]]
) {
const uint lane = tid.x;
if (lane >= THREADGROUP_SIZE) {
return;
}
// One 64x64 output tile per threadgroup.
// Grid x dim is scaled by threadgroup size, so we recover group index.
const uint group_x = (gid.x - tid.x) / THREADGROUP_SIZE;
const uint group_y = gid.y;
const uint tile_m = group_y * TILE_M;
const uint tile_n = group_x * TILE_N;
const uint packed_stride = (N + FP4_PER_WORD - 1u) / FP4_PER_WORD;
const uint safe_group_size = max(group_size, 1u);
// Thread mapping:
// 8 row blocks x 4 col blocks across 32 threads.
// Each thread computes an 8x16 micro-tile.
// (32 threads * 8 rows * 16 cols = 64 * 64 elements)
const uint row_block = lane & 0x7u; // lane % 8
const uint col_block = lane >> 3; // lane / 8
const uint row_base = row_block * THREAD_ROWS;
const uint col_base = col_block * THREAD_COLS;
threadgroup half A_tile[TILE_M][K_UNROLL];
threadgroup half B_tile[K_UNROLL][TILE_N];
float acc[THREAD_ROWS][THREAD_COLS];
#pragma unroll
for (uint mi = 0; mi < THREAD_ROWS; ++mi) {
#pragma unroll
for (uint nj = 0; nj < THREAD_COLS; ++nj) {
acc[mi][nj] = 0.0f;
}
}
// K mainloop with 4-way unroll per stage.
for (uint k0 = 0; k0 < K; k0 += K_UNROLL) {
// Cooperative load of A tile slice [64, 4].
// 32 threads load 64*4=256 elements -> 8 elements per thread.
#pragma unroll
for (uint i = 0; i < LOADS_PER_THREAD; ++i) {
const uint flat = lane * LOADS_PER_THREAD + i;
const uint a_row = flat / K_UNROLL;
const uint ku = flat % K_UNROLL;
const uint g_row = tile_m + a_row;
const uint g_k = k0 + ku;
half a_val = half(0.0h);
if (g_row < M && g_k < K) {
a_val = A[g_row * K + g_k];
}
A_tile[a_row][ku] = a_val;
}
// Cooperative load + on-the-fly dequant of B tile slice [4, 64].
// 32 threads load 4*64=256 elements -> 8 elements per thread.
#pragma unroll
for (uint i = 0; i < LOADS_PER_THREAD; ++i) {
const uint flat = lane * LOADS_PER_THREAD + i;
const uint ku = flat / TILE_N;
const uint b_col = flat % TILE_N;
const uint g_k = k0 + ku;
const uint g_col = tile_n + b_col;
half b_val = half(0.0h);
if (g_k < K && g_col < N) {
const uint packed_idx = g_k * packed_stride + (g_col >> 3);
const uint32_t packed = B_packed[packed_idx];
const uint nibble_shift = (g_col & 0x7u) * 4u;
const uint nibble = (packed >> nibble_shift) & 0xFu;
const uint scale_row = g_k / safe_group_size;
const half scale = B_scales[scale_row * N + g_col];
b_val = dequant_fp4_e2m1(nibble, scale);
}
B_tile[ku][b_col] = b_val;
}
threadgroup_barrier(mem_flags::mem_threadgroup);
// Compute 8x16 outer products accumulating into acc.
#pragma unroll
for (uint ku = 0; ku < K_UNROLL; ++ku) {
#pragma unroll
for (uint mi = 0; mi < THREAD_ROWS; ++mi) {
const float a_val = float(A_tile[row_base + mi][ku]);
#pragma unroll
for (uint nj = 0; nj < THREAD_COLS; ++nj) {
acc[mi][nj] = fma(a_val, float(B_tile[ku][col_base + nj]), acc[mi][nj]);
}
}
}
threadgroup_barrier(mem_flags::mem_threadgroup);
}
// Store results
#pragma unroll
for (uint mi = 0; mi < THREAD_ROWS; ++mi) {
const uint g_row = tile_m + row_base + mi;
if (g_row >= M) {
continue;
}
#pragma unroll
for (uint nj = 0; nj < THREAD_COLS; ++nj) {
const uint g_col = tile_n + col_base + nj;
if (g_col < N) {
C[g_row * N + g_col] = half(acc[mi][nj]);
}
}
}
}

